60	    function cleanMarkdown(text) {
61	        return text
62	            // Clean up excessive newlines
63	            .replace(/\n{3,}/g, '\n\n')
64	            // Remove any HTML entities that might have leaked through
65	            .replace(/&lt;/g, '<')
66	            .replace(/&gt;/g, '>')
67	            .replace(/&amp;/g, '&')
68	            .replace(/&nbsp;/g, ' ')
69	            .replace(/&quot;/g, '"')
70	            // Clean up whitespace at the start of lines (but preserve code block indentation)
71	            .replace(/^[ \t]+(?!```)/gm, '')
72	            .trim();
73	    }
74	
75	    function escapeMarkdownText(text) {
76	        // Escape special markdown characters in regular text
77	        return text
78	            .replace(/\\/g, '\\\\')
79	            .replace(/\[/g, '\\[')
80	            .replace(/\]/g, '\\]');
81	    }
