156	    function convertElementToMarkdown(element) {
157	        if (!element) return '';
158	
159	        // Handle text nodes
160	        if (element.nodeType === Node.TEXT_NODE) {
161	            return element.textContent || '';
162	        }
163	
164	        // Skip non-element nodes
165	        if (element.nodeType !== Node.ELEMENT_NODE) {
166	            return '';
167	        }
168	
169	        const tagName = element.tagName.toLowerCase();
170	
171	        // Skip UI elements (but check button for images first)
172	        if (tagName === 'button') {
173	            // Check if button contains an image (ChatGPT wraps images in buttons)
174	            const img = element.querySelector('img');
175	            if (img) {
176	                return convertElementToMarkdown(img);
177	            }
178	            return '';
179	        }
180	        if (['svg', 'script', 'style', 'noscript'].includes(tagName)) {
181	            return '';
182	        }
183	
184	        // Skip elements with specific classes (UI components)
185	        const className = element.className || '';
186	        if (typeof className === 'string' &&
187	            (className.includes('copy') || className.includes('edit') ||
188	             className.includes('regenerate') || className.includes('citation-pill'))) {
189	            return '';
190	        }
191	
192	        // Process by tag type
193	        switch (tagName) {
194	            // Headings
195	            case 'h1':
196	                return '\n\n# ' + getTextContent(element) + '\n\n';
197	            case 'h2':
198	                return '\n\n## ' + getTextContent(element) + '\n\n';
199	            case 'h3':
200	                return '\n\n### ' + getTextContent(element) + '\n\n';
201	            case 'h4':
202	                return '\n\n#### ' + getTextContent(element) + '\n\n';
203	            case 'h5':
204	                return '\n\n##### ' + getTextContent(element) + '\n\n';
205	            case 'h6':
206	                return '\n\n###### ' + getTextContent(element) + '\n\n';
207	
208	            // Paragraph
209	            case 'p':
210	                return '\n\n' + processChildNodes(element) + '\n\n';
211	
212	            // Bold
213	            case 'strong':
214	            case 'b':
215	                return '**' + processChildNodes(element) + '**';
216	
217	            // Italic
218	            case 'em':
219	            case 'i':
220	                return '*' + processChildNodes(element) + '*';
221	
222	            // Code (inline)
223	            case 'code':
224	                // Check if it's inside a pre block
225	                if (element.parentElement && element.parentElement.tagName.toLowerCase() === 'pre') {
226	                    return element.textContent || '';
227	                }
228	                return '`' + (element.textContent || '') + '`';
229	
230	            // Code blocks
231	            case 'pre': {
232	                const codeEl = element.querySelector('code');
233	                const code = element.textContent || '';
234	                let lang = '';
235	                if (codeEl) {
236	                    const langMatch = codeEl.className.match(/language-([a-zA-Z0-9]+)/);
237	                    lang = langMatch ? langMatch[1] : '';
238	                }
239	                return '\n\n```' + lang + '\n' + code.trim() + '\n```\n\n';
240	            }
241	
242	            // Lists
243	            case 'ul':
244	            case 'ol':
245	                return '\n\n' + convertListToMarkdown(element) + '\n\n';
246	
247	            // Tables
248	            case 'table':
249	                return convertTableToMarkdown(element);
250	
251	            // Images
252	            case 'img': {
253	                const src = element.getAttribute('src') || '';
254	                const alt = element.getAttribute('alt') || '';
255	                // Skip UI images (favicons, avatars, icons)
256	                if (src.includes('favicon') || src.includes('avatar') ||
257	                    className.includes('icon') || (element.width && element.width < 48)) {
258	                    return '';
259	                }
260	                // Check for pre-converted base64 data
261	                const base64Data = element.getAttribute('data-base64');
262	                if (base64Data) {
263	                    const imgAlt = (alt && !alt.startsWith('http')) ? alt : 'Image';
264	                    return `\n\n![${imgAlt}](${base64Data})\n\n`;
265	                }
266	                // Fallback: use original src (remove blob: prefix if present)
267	                let imgSrc = src;
268	                if (src.startsWith('blob:')) {
269	                    imgSrc = src.substring(5);
270	                }
271	                const imgAlt = (alt && !alt.startsWith('http')) ? alt : 'Image';
272	                return `\n\n![${imgAlt}](${imgSrc})\n\n`;
273	            }
274	
275	            // Canvas
276	            case 'canvas':
277	                return '\n\n[Canvas Image]\n\n';
278	
279	            // Line break
280	            case 'br':
281	                return '\n';
282	
283	            // Horizontal rule
284	            case 'hr':
285	                return '\n\n---\n\n';
286	
287	            // Links
288	            case 'a': {
289	                const href = (element.getAttribute('href') || '').trim();
290	                const lowerHref = href.toLowerCase();
291	                if (!href || lowerHref.startsWith('javascript:') ||
292	                    lowerHref.startsWith('data:') || lowerHref.startsWith('vbscript:') ||
293	                    href.startsWith('#')) {
294	                    return processChildNodes(element);
295	                }
296	                const text = getTextContent(element) || href;
297	                const escapedText = escapeMarkdownText(text);
298	                const safeHref = href.replace(/\\/g, '%5C').replace(/\)/g, '%29');
299	                return `[${escapedText}](${safeHref})`;
300	            }
301	
302	            // Blockquote
303	            case 'blockquote':
304	                return '\n\n> ' + processChildNodes(element).replace(/\n/g, '\n> ') + '\n\n';
305	
306	            // Span and other inline elements - just process children
307	            case 'span':
308	            case 'div':
309	            case 'article':
310	            case 'section':
311	            case 'main':
312	            case 'header':
313	            case 'footer':
314	            case 'aside':
315	            case 'nav':
316	                return processChildNodes(element);
317	
318	            // Skip hidden elements
319	            case 'template':
320	                return '';
321	
322	            default:
323	                return processChildNodes(element);
324	        }
325	    }
