327	    function getTextContent(element) {
328	        // Get text content while respecting structure
329	        return processChildNodes(element).replace(/\n+/g, ' ').trim();
330	    }
331	
332	    function processChildNodes(element) {
333	        let result = '';
334	        element.childNodes.forEach(child => {
335	            result += convertElementToMarkdown(child);
336	        });
337	        return result;
338	    }
