340	    async function processMessageContent(element) {
341	        const clone = element.cloneNode(true);
342	
343	        // Extract images from buttons before removing them (ChatGPT wraps images in buttons)
344	        clone.querySelectorAll('button').forEach(btn => {
345	            const img = btn.querySelector('img');
346	            if (img) {
347	                // Replace button with the image
348	                btn.parentNode.replaceChild(img.cloneNode(true), btn);
349	            } else {
350	                btn.remove();
351	            }
352	        });
353	
354	        // Convert KaTeX-rendered math back to TeX source ($...$ inline, $$...$$ block).
355	        // KaTeX duplicates the equation as both MathML (with original TeX in
356	        // <annotation encoding="application/x-tex">) and a deeply nested HTML render —
357	        // grab the annotation so we get the author's source rather than the visual goo.
358	        clone.querySelectorAll('.katex').forEach(katex => {
359	            const annotation = katex.querySelector('annotation[encoding="application/x-tex"]');
360	            if (!annotation) return;
361	            const tex = (annotation.textContent || '').trim();
362	            if (!tex) return;
363	            const displayWrapper = katex.closest('.katex-display');
364	            const isDisplay = !!displayWrapper;
365	            const replacement = clone.ownerDocument.createElement(isDisplay ? 'div' : 'span');
366	            replacement.setAttribute('data-tex', '1');
367	            replacement.textContent = isDisplay ? `\n\n$$${tex}$$\n\n` : `$${tex}$`;
368	            const target = displayWrapper || katex;
369	            target.parentNode.replaceChild(replacement, target);
370	        });
371	
372	        // Remove UI elements that shouldn't be in the export
373	        clone.querySelectorAll('svg, [class*="sr-only"], [class*="citation-pill"]').forEach(el => el.remove());
374	
375	        // Pre-convert all images to base64
376	        const images = clone.querySelectorAll('img');
377	        const originalImages = element.querySelectorAll('img');
378	
379	        // Create a map of src -> original img element for base64 conversion
380	        const srcToOriginal = new Map();
381	        originalImages.forEach(img => {
382	            const src = img.getAttribute('src');
383	            if (src && !srcToOriginal.has(src)) {
384	                srcToOriginal.set(src, img);
385	            }
386	        });
387	
388	        // Convert each image to base64
389	        for (const img of images) {
390	            const src = img.getAttribute('src') || '';
391	            // Skip small icons and UI images
392	            if (src.includes('favicon') || src.includes('avatar') ||
393	                (img.className && img.className.includes('icon'))) {
394	                continue;
395	            }
396	
397	            // Use original image element for conversion (it has the actual image data)
398	            const originalImg = srcToOriginal.get(src);
399	            if (originalImg) {
400	                const base64 = await imageToBase64(originalImg);
401	                if (base64) {
402	                    img.setAttribute('data-base64', base64);
403	                }
404	            }
405	        }
406	
407	        // Find the markdown content container if it exists.
408	        // Skip narrowing for Claude — the response wrapper already is the content
409	        // container, and it holds multiple .standard-markdown blocks we must keep.
410	        const isClaudeMessage = (clone.classList && clone.classList.contains('font-claude-response')) ||
411	                                clone.getAttribute('data-testid') === 'user-message';
412	        let contentElement = clone;
413	        if (!isClaudeMessage) {
414	            const markdownContainer = clone.querySelector('.markdown, [class*="markdown"]');
415	            if (markdownContainer) contentElement = markdownContainer;
416	        }
417	
418	        // Convert to markdown
419	        let markdown = convertElementToMarkdown(contentElement);
420	
421	        // Clean up the result
422	        return cleanMarkdown(markdown);
423	    }
