430	    function findMessages() {
431	        // More specific selectors to avoid nested elements
432	        const selectors = [
433	            'div[data-message-author-role]', // Modern ChatGPT with clear author role
434	            'article[data-testid*="conversation-turn"]', // Conversation turns
435	            'div[data-testid="conversation-turn"]', // Specific conversation turn
436	            'div[data-testid="user-message"], div.font-claude-response', // Claude (user + assistant)
437	            '.group\\/conversation-turn', // Fix for issue #6: More specific selector for conversation turns
438	            'div[class*="group"]:not([class*="group"] [class*="group"])', // Top-level groups only
439	        ];
440	
441	        let messages = [];
442	        for (const selector of selectors) {
443	            messages = document.querySelectorAll(selector);
444	            if (messages.length > 0) {
445	                console.log(`Using selector: ${selector}, found ${messages.length} messages`);
446	                break;
447	            }
448	        }
449	
450	        if (messages.length === 0) {
451	            // Fallback: try to find conversation container and parse its structure
452	            const conversationContainer = document.querySelector('[role="main"], main, .conversation, [class*="conversation"]');
453	            if (conversationContainer) {
454	                // Look for direct children that seem like message containers
455	                messages = conversationContainer.querySelectorAll(':scope > div, :scope > article');
456	                console.log(`Fallback: found ${messages.length} potential messages in conversation container`);
457	            }
458	        }
459	
460	        // Filter and validate messages
461	        const validMessages = Array.from(messages).filter(msg => {
462	            const text = msg.textContent.trim();
463	
464	            // Must have some content (reduced threshold for Chinese text)
465	            if (text.length < 5) return false;
466	            if (text.length > 100000) return false;
467	
468	            // Skip elements that are clearly UI components
469	            if (msg.querySelector('input[type="text"], textarea')) return false;
470	            if (msg.classList.contains('typing') || msg.classList.contains('loading')) return false;
471	
472	            return true;
473	        });
474	
475	        // Remove nested messages and consolidate content
476	        const consolidatedMessages = [];
477	        const usedElements = new Set();
478	
479	        validMessages.forEach(msg => {
480	            if (usedElements.has(msg)) return;
481	            
482	            // Check if this message is nested within another valid message
483	            const isNested = validMessages.some(other => 
484	                other !== msg && other.contains(msg) && !usedElements.has(other)
485	            );
486	            
487	            if (!isNested) {
488	                consolidatedMessages.push(msg);
489	                usedElements.add(msg);
490	            }
491	        });
492	
493	        return consolidatedMessages;
494	    }
