496	    function findReplyLabel(messageElement) {
497	        // Look for reply labels like "回复 1", "回复 2" in sibling or parent elements
498	        const parent = messageElement.closest('.flex.max-w-full');
499	        if (parent && parent.previousElementSibling) {
500	            const labelEl = parent.previousElementSibling.querySelector('.font-semibold, [class*="font-semibold"]');
501	            if (labelEl) {
502	                const text = labelEl.textContent.trim();
503	                if (/^回复\s*\d+$/.test(text) || /^Response\s*\d+$/i.test(text)) {
504	                    return text;
505	                }
506	            }
507	        }
508	        // Also check parent's parent
509	        const grandParent = messageElement.parentElement?.parentElement;
510	        if (grandParent) {
511	            const labels = grandParent.querySelectorAll('.font-semibold, [class*="font-semibold"]');
512	            for (const label of labels) {
513	                const text = label.textContent.trim();
514	                if (/^回复\s*\d+$/.test(text) || /^Response\s*\d+$/i.test(text)) {
515	                    return text;
516	                }
517	            }
518	        }
519	        return null;
520	    }
