522	    function identifySender(messageElement, index, allMessages) {
523	        // Method 1: Check for data attributes (most reliable)
524	        const authorRole = messageElement.getAttribute('data-message-author-role');
525	        if (authorRole) {
526	            return { sender: authorRole === 'user' ? 'You' : 'ChatGPT', reliable: true };
527	        }
528	
529	        // Claude: user message and assistant response have distinct markers
530	        if (messageElement.getAttribute('data-testid') === 'user-message') {
531	            return { sender: 'You', reliable: true };
532	        }
533	        if (messageElement.classList && messageElement.classList.contains('font-claude-response')) {
534	            return { sender: 'Claude', reliable: true };
535	        }
536	
537	        // Method 2: Look for avatar images with better detection
538	        const avatars = messageElement.querySelectorAll('img');
539	        for (const avatar of avatars) {
540	            const alt = avatar.alt?.toLowerCase() || '';
541	            const src = avatar.src?.toLowerCase() || '';
542	            const classes = avatar.className?.toLowerCase() || '';
543	
544	            // User indicators
545	            if (alt.includes('user') || src.includes('user') || classes.includes('user')) {
546	                return { sender: 'You', reliable: false };
547	            }
548	
549	            // Assistant indicators
550	            if (alt.includes('chatgpt') || alt.includes('assistant') || alt.includes('gpt') ||
551	                src.includes('assistant') || src.includes('chatgpt') || classes.includes('assistant')) {
552	                return { sender: 'ChatGPT', reliable: false };
553	            }
554	        }
555	
556	        // Method 3: Content analysis with better patterns
557	        const text = messageElement.textContent.toLowerCase();
558	        const textStart = text.substring(0, 200); // Look at beginning of message
559	
560	        // Strong ChatGPT indicators
561	        if (textStart.match(/^(i understand|i can help|here's|i'll|let me|i'd be happy|certainly|of course)/)) {
562	            return { sender: 'ChatGPT', reliable: false };
563	        }
564	
565	        // Strong user indicators
566	        if (textStart.match(/^(can you|please help|how do i|i need|i want|help me|could you)/)) {
567	            return { sender: 'You', reliable: false };
568	        }
569	
570	        // Method 4: Structural analysis - look at DOM structure
571	        const hasCodeBlocks = messageElement.querySelectorAll('pre, code').length > 0;
572	        const hasLongText = messageElement.textContent.length > 200;
573	        const hasLists = messageElement.querySelectorAll('ul, ol, li').length > 0;
574	
575	        // ChatGPT messages tend to be longer and more structured
576	        if (hasCodeBlocks && hasLongText && hasLists) {
577	            return { sender: 'ChatGPT', reliable: false };
578	        }
579	
580	        // Method 5: Position-based fallback with better logic
581	        // Try to detect actual alternating pattern by looking at content characteristics
582	        if (index > 0 && allMessages[index - 1]) {
583	            const prevText = allMessages[index - 1].textContent;
584	            const currentText = messageElement.textContent;
585	
586	            // If previous was short and current is long, likely user -> assistant
587	            if (prevText.length < 100 && currentText.length > 300) {
588	                return { sender: 'ChatGPT', reliable: false };
589	            }
590	
591	            // If previous was long and current is short, likely assistant -> user
592	            if (prevText.length > 300 && currentText.length < 100) {
593	                return { sender: 'You', reliable: false };
594	            }
595	        }
596	
597	        // Final fallback
598	        return { sender: index % 2 === 0 ? 'You' : 'ChatGPT', reliable: false };
599	    }
